 ///     open spec fn ens(self, x: X, y: Y) -> bool { atomic_post }
 ///
 ///     open spec fn outer_mask(self) -> ISet<int> { Eo }
 ///     open spec fn inner_mask(self) -> ISet<int> { Ei }
