     pub open spec fn is_commit(self) -> bool {
         match self {
             UpdateControlFlow::Commit => true,
             UpdateControlFlow::Abort => false,
         }
     }

     pub open spec fn is_abort(self) -> bool {
         !self.is_commit()
     }
